// Fetches NJ Rules of Court data from inside a real browser session, for when
// njcourts.gov's bot protection blocks build-nj-rules.py. Generated by
// `build-nj-rules.py --browser-script`, which fills in START with the requests
// the local cache is missing.
//
// Open https://www.njcourts.gov/attorneys/rules-of-court in Chrome, open
// DevTools > Console, paste this script and press Enter. Leave the tab open
// until it downloads nj-rules-fetch.json (njDownload() saves what it has so
// far at any point), then run:
//   python .github/scripts/build-nj-rules.py --import nj-rules-fetch.json
(async () => {
  const START = __START__;
  const PARTS = ["Part 1", "Part 2", "Part 3", "Part 4", "Part 5", "Part 6"];
  const DELAY = 3000;                     // ms between requests; faster runs get blocked
  const BACKOFF = [60, 180, 600];         // seconds to wait after each block before giving up
  const API = "/njcourts_rules_of_court/";
  const out = {};
  const queue = START.slice();
  const seen = new Set();
  const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

  window.njDownload = () => {
    const blob = new Blob([JSON.stringify(out)], { type: "application/json" });
    const a = document.createElement("a");
    a.href = URL.createObjectURL(blob);
    a.download = "nj-rules-fetch.json";
    a.click();
  };

  function enqueueNode(node) {
    queue.push(API + "get-term?tid=" + node.key);
    if (node.lazy !== false) queue.push(API + "subtree?tid=" + node.key);
  }

  async function fetchBody(path) {
    for (let attempt = 0; attempt <= BACKOFF.length; attempt++) {
      try {
        const r = await fetch(path, { credentials: "same-origin" });
        const body = await r.text();
        if (r.ok && !body.includes("Pardon Our Interruption")) {
          if (path.startsWith(API)) JSON.parse(body);
          return body;
        }
      } catch (e) {}
      if (attempt === BACKOFF.length) break;
      console.warn("Blocked on " + path + "; waiting " + BACKOFF[attempt] + "s before retrying");
      await sleep(BACKOFF[attempt] * 1000);
    }
    return null;
  }

  let done = 0;
  let blocked = false;
  while (queue.length) {
    const path = queue.shift();
    if (seen.has(path)) continue;
    seen.add(path);
    const body = await fetchBody(path);
    if (body === null) {
      blocked = true;
      break;
    }
    out[path] = body;
    if (path === API + "tree") {
      JSON.parse(body).filter((c) => PARTS.includes(c.section)).forEach(enqueueNode);
    } else if (path.startsWith(API + "subtree")) {
      (JSON.parse(body) || []).forEach(enqueueNode);
    }
    done++;
    if (done % 25 === 0) console.log(done + " fetched, " + queue.length + " queued");
    await sleep(DELAY);
  }
  if (blocked) {
    console.error("STOPPED EARLY (blocked) after " + done + " responses. Saving what was fetched; import it, then generate and run a fresh script.");
  } else {
    console.log("Finished: all " + done + " responses fetched.");
  }
  window.njDownload();
})();
